-- 2026-10-04 마감된 crawl-rda-* 행 정정 — 주관 기관·신청 기간·요약 (DE-A 후속 3)
--
-- 문제:
--   sync-crawl 의 RDA(똑똑!청년농부) 수집기가 목록만 읽어 주관 기관을 "농촌진흥청"(포털 운영 기관일 뿐)으로,
--   신청 시작일을 수집일로, 요약을 "…에서 수집했어요"(정보량 0)로 채웠다. 수집기는 10/3 상세 페이지 보강으로
--   고쳤고(진행 중 14행은 refresh 재적재로 바로잡힘), 목록에서 빠진 마감 행 142행은 이 파일로 바로잡는다.
--
-- 대상 (2026-10-04 운영 DB anon GET 실측, status = '마감'):
--   support_programs   56행 → UPDATE 56행
--   education_courses  86행 → UPDATE 86행
--   삭제된 원문 게시글 0행 → link_status = 'broken' 만 (다른 값은 근거가 없어 그대로)
--   UPDATE 하지 않은 행 0행
--
-- 값의 출처:
--   각 행 원문 상세(https://www.rda.go.kr/young/custom/{policy|edu}/view.do?sId=)를 2026-10-04 읽기 전용 GET 으로
--   순차 조회(요청 간 1.3초, 설명형 UA)해 운영 수집기와 같은 함수로 해석했다
--   (supabase/functions/_shared/crawl-utils.ts parseRdaDetailHtml · applyRdaDetail).
--   · 주관 기관 = 상세 표 '주관기관'(없으면 담당기관, 그것도 없으면 지역 표기) — "농촌진흥청" 채움 금지
--   · 신청 기간 = 상세 '신청기간' (resolveRdaWindow: 마감일을 모르면 9999 페어, 시작일만 모르면 시작 9999)
--     — 수집일 채움 금지. 상세에 마감일이 없을 때만 DB 마감일(옛 목록 값)을 쓰되, 시작=마감(둘 다 수집일)이면 버린다
--   · 요약 = 상세 '요약내용'에서 원문 문장 발췌 (extractRdaSummary, 최대 200자).
--     공공누리 "변경금지·상업적이용금지" 고지가 있는 공고는 발췌하지 않고 빈 문자열 — 화면이 빈 요약을 숨긴다
--   · status = 새 신청 기간과 적용 시점 KST 오늘로 다시 매긴다 (windowStatus 와 같은 규칙)
--
-- 멱등·안전장치:
--   · WHERE organization = '농촌진흥청' — 새 수집기(refresh)가 이미 고친 행은 건드리지 않는다
--   · 한 트랜잭션. 생성 스크립트는 일회성이라 삭제했다 (값은 이 파일이 원본)
--
-- 적용 후 확인 (읽기 전용):
--   SELECT count(*) FROM support_programs  WHERE slug LIKE 'crawl-rda-%' AND organization = '농촌진흥청';
--   SELECT count(*) FROM education_courses WHERE slug LIKE 'crawl-rda-%' AND organization = '농촌진흥청';
--   → 진행 중 행(지원사업 5·교육 9)은 sync-crawl refresh 전까지 남는다. refresh 후 0 + 위 미처리 행 수
--   SELECT count(*) FROM education_courses WHERE slug LIKE 'crawl-rda-%' AND description LIKE '%에서 수집%';
--
-- ⚠ apply 는 회장 결재 후 수동 (Supabase Dashboard SQL Editor). sync-crawl 배포와 순서 무관.

BEGIN;

-- ── 1. 지원사업 56행 ─────────────────────────────────────────────
UPDATE support_programs AS p
SET organization      = v.organization,
    application_start = v.application_start,
    application_end   = v.application_end,
    summary           = v.summary,
    status            = CASE
      WHEN v.application_end = DATE '9999-12-31' THEN '모집예정'
      WHEN v.application_end < (now() AT TIME ZONE 'Asia/Seoul')::date THEN '마감'
      WHEN v.application_start <> DATE '9999-12-31'
       AND v.application_start > (now() AT TIME ZONE 'Asia/Seoul')::date THEN '모집예정'
      ELSE '모집중'
    END,
    updated_at        = now()
FROM (VALUES
  ('crawl-rda-programs-0125ca38', '김포시농업기술센터', DATE '2026-06-23', DATE '2026-07-24', '지원내용 : 청년농업인 아이디어 실현을 위한 유형별 기반 조성, 시설, 설비, 장비·기계 도입 지원, 신기술 적용을 통한 생산비 절감 및 국내 육성 품종 확대 지원 · 사 업 비: 개소당 100백만원（보조 80백만원, 자부담 20백만원）'),
  ('crawl-rda-programs-02ae3542', '달성군농업기술센터', DATE '2026-06-01', DATE '2026-07-10', '신청대상 : 사업 시행연도 기준 18세~39세(1986~2008년도 출생자)'),
  ('crawl-rda-programs-032e715e', '영암군농업기술센터', DATE '2026-06-22', DATE '2026-07-03', '신청자격 : 전체 영농경력 20년 이상이거나 동일영농분야 15년 이상 경력을 가진 농업인, 「농업ㆍ농촌 및 식품산업 기본법」제3조제2호에 따른 농업인 자격을 갖춘, 생산을 기본으로 하면서 생산기술개발, 가공, 유통, 상품화 등 해당분야 최고수준의 기술을 보유하고 장인정신이 투철한 농업인'),
  ('crawl-rda-programs-0aa10e02', '옥천군농업기술센터', DATE '2026-09-02', DATE '2026-09-21', '지원자격 및 요건 : 사업 시행연도 기준 만18세이상~만40세미만 농업인(86.1.1. ~ 08.12.31. 출생자), 26.1.1.기준, 충북 도내 주민등록을 두고 6개월 이상 거주하고 있는자'),
  ('crawl-rda-programs-0c6bfbcd', '양평군농업기술센터', DATE '2026-06-25', DATE '2026-07-24', '경기도 청년농업인의 영농 조기정착 및 경쟁력을 향상하기 위하여, 2026년 청년농업인 아이디어 사업화 공모사업 모집공고를 게재하고자 하오니, 관내 관심있는 청년농업인들의 사업을 신청하여 주시기 바랍니다. 사업대상: 18세 이상 ~ 39세 이하의 청년농업인으로 병역필(후계농업경영인 산업기능요원 복무자 가능) 또는 면제자(최근 3년이상 영농종사자)'),
  ('crawl-rda-programs-0fa54ebc', '순천시농업기술센터', DATE '2026-07-31', DATE '2026-09-11', '사업비 : 450백만원 / 개소당 150백만원(재원비율 : 도비 30%, 시비 50%, 자담 20%)'),
