  AND p.organization = '농촌진흥청';

-- ── 2. 교육 86행 ────────────────────────────────────────────────
UPDATE education_courses AS e
SET organization      = v.organization,
    application_start = v.application_start,
    application_end   = v.application_end,
    description       = v.description,
    status            = CASE
      WHEN v.application_end = DATE '9999-12-31' THEN '모집예정'
      WHEN v.application_end < (now() AT TIME ZONE 'Asia/Seoul')::date THEN '마감'
      WHEN v.application_start <> DATE '9999-12-31'
       AND v.application_start > (now() AT TIME ZONE 'Asia/Seoul')::date THEN '모집예정'
      ELSE '모집중'
    END,
    updated_at        = now()
FROM (VALUES
